    textoApoio: TEXTO_UNESP_2025_A_5,
    imagem: IMG_UNESP_2025_A_CACAU, legendaAcima: LEG_UNESP_2025_A_CACAU,
    enunciado: `<p>O gráfico 1, “Price, $’000 per tonne”, reflete as informações do texto presentes</p>`,
    alternativas: [
      { letra: 'A', texto: 'no segundo parágrafo, apenas.' },
      { letra: 'B', texto: 'no terceiro parágrafo, apenas.' },
      { letra: 'C', texto: 'no primeiro parágrafo, apenas.', explicacao: 'Correta! O gráfico 1 mostra o preço do cacau subindo a partir de 2022 até um recorde em 2024 — exatamente o que diz o primeiro parágrafo (“began creeping up in the second half of 2022... it has doubled, reaching an all-time high in January 2024”). Os outros parágrafos tratam de causas, não da série de preços.' },
      { letra: 'D', texto: 'no primeiro e no terceiro parágrafos.' },
      { letra: 'E', texto: 'no segundo e no terceiro parágrafos.' },
    ],
